const progress = (msg) => { status(msg); const m = /([\d.]+) ?\/ ?([\d.]+) MB/.exec(msg || ""); $("#progbar").style.width = m ? (100 * +m[1] / +m[2]).toFixed(0) + "%" : (msg ? "30%" : "0%"); };
const lab = a => a.choice ?? (a.score != null ? a.score.toFixed(2) : (a.noul ? "yes" : "no"));
const labJa = a => a.choice ?? (a.level != null ? a.level : (a.noul ? "はい" : "いいえ"));
const confCls = c => c >= 0.7 ? "hi" : c >= 0.5 ? "mid" : "lo";
const confTxt = c => (c >= 0.7 ? "確信 " : c >= 0.5 ? "やや " : "不確か ") + pc(c);
