$("#o-run").onclick = async () => { const q = $("#o-q").value.trim(); if (!q) { $("#o-q").focus(); return status("キーワードを入れてください"); } $("#o-run").disabled = true; showSteps(false); try { await doCollect(q); } catch (e) { status("収集エラー: " + e.message); } $("#o-run").disabled = false; if (isMobile) $("#o-summary").scrollIntoView({ behavior: "smooth", block: "start" }); };
$("#o-watch").onclick = async () => { const qs = savedQueries(); if (!qs.length) return status("履歴がありません（まず 1 回収集してください）"); $("#o-run").disabled = true; const all = []; let nNew = 0; for (const q of qs.slice(0, 8)) { $("#o-q").value = q; try { await doCollect(q, { silentHistory: true }); } catch { continue; } const fresh = oItems.filter(i => !i.error && i.is_new); nNew += fresh.length; all.push(`${q}: 新着 ${fresh.length} 件`); } $("#o-run").disabled = false; $("#o-only-new").checked = true; botSay(`🔔 保存した検索 ${Math.min(8, qs.length)} 件を再収集：新着 ${nNew} 件<br>` + all.map(esc).join("<br>")); status(`再収集完了: 新着 ${nNew} 件（最後の検索を表示中。「新着のみ」ON）`); renderOsint(); };
