const needsCheck = (it, j) => j && (contra(j) || j.asks_spread?.noul || (relevant(j) && j.kind?.choice === "一般の投稿・目撃" && j.urgency?.score >= 3));
function renderOsint() { const nOk = oItems.filter(i => !i.error).length; const nCl = oClusters ? new Set(Object.values(oClusters)).size : null; const ts = oJudged ? oItems.map((it, i) => trustScore(it, oJudged[i], W)) : null;
  const thHi = +$("#o-th-hi").value, thLo = +$("#o-th-lo").value; const tri = ts ? oItems.map((it, i) => it.error || !ts[i] ? null : needsCheck(it, oJudged[i]) ? "check" : ts[i].score >= thHi ? "auto" : ts[i].score < thLo ? "drop" : "check") : null; const nCheck = tri ? tri.filter(x => x === "check").length : nOk;
  $("#o-triage-box").classList.toggle("hidden", !ts);
  $("#o-stats").innerHTML = `<span class="stat">取得<br><b>${nOk}</b></span>${tri ? `<span class="stat" title="信頼性がしきい値以上で要確認フラグなし">自動採用<br><b class="ok">${tri.filter(x => x === "auto").length}</b></span><span class="stat">人手確認<br><b class="warn">${nCheck}</b></span><span class="stat">除外<br><b class="muted">${tri.filter(x => x === "drop").length}</b></span><span class="stat" title="JEV により人が読む件数がどれだけ減ったか">読む件数<br><b>${nOk} → ${nCheck}</b> <span class="small muted">(−${nOk ? Math.round(100 * (1 - nCheck / nOk)) : 0}%)</span></span><span class="stat" title="端末内・送信なし・生成なし">JEV<br><b>${oStats.judged}</b> 判定 / ${(oStats.ms / 1000).toFixed(1)} s</span>` : ""}${nCl != null ? `<span class="stat">類似群<br><b>${nCl}</b></span>` : ""}${oGeo.length ? `<span class="stat">地理根拠<br><b>${oGeo.length}</b></span>` : ""}${ts ? `<span class="stat">高信頼(≥70)<br><b>${ts.filter(t => t && t.score >= 0.7).length}</b></span><span class="stat">要確認<br><b class="warn">${oItems.filter((it, i) => needsCheck(it, oJudged[i])).length}</b></span>` : ""}`;
  if (oJudged) { const kinds = {}; oJudged.forEach(j => { if (j?.kind) kinds[j.kind.choice] = (kinds[j.kind.choice] || 0) + 1; }); const top = [...oItems.keys()].filter(i => ts[i]).sort((a, b) => ts[b].score - ts[a].score).slice(0, 3); const chk = [...oItems.keys()].filter(i => needsCheck(oItems[i], oJudged[i])); const urg = [...oItems.keys()].filter(i => oJudged[i]?.urgency?.score >= 3.5); const contra_ = [...oItems.keys()].filter(i => contra(oJudged[i]));
    $("#o-summary").innerHTML = `<div class="summary"><b>JEV の要約</b>（${esc(jev?.name || "")}）<div class="small">${Object.entries(kinds).map(([k, v]) => `<span class="pill">${esc(k)} ${v}</span>`).join(" ")}</div><div class="small">信頼性の高い順: ${top.map(i => `#${i} ${esc((oItems[i].title || "").slice(0, 30))}（${(ts[i].score * 100).toFixed(0)}）`).join(" ／ ") || "—"}</div>${urg.length ? `<div class="small">緊急度が高い: ${urg.map(i => "#" + i).join(", ")}</div>` : ""}${contra_.length ? `<div class="small bad">根拠と矛盾の疑い: ${contra_.map(i => "#" + i).join(", ")}（根拠欄と本文を見比べる）</div>` : ""}${chk.length ? `<div class="small warn">要確認 ${chk.length} 件（矛盾・拡散依頼・一般投稿の高緊急）: ${chk.map(i => "#" + i).join(", ")}</div>` : `<div class="small ok">要確認なし</div>`}</div>`; }
  const flt = $("#o-filter").value.trim().split(/[,、\s]+/).filter(Boolean); const hl = t => { let s = esc(t); for (const f of flt) s = s.replace(new RegExp(f.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "gi"), m => `<mark>${m}</mark>`); return s; };
  const sortBy = $("#o-sort").value; const keyOf = i => sortBy === "time" ? (oItems[i].time || "") : sortBy === "source" ? oItems[i].source : sortBy === "urgency" ? (oJudged?.[i]?.urgency?.score ?? -1) : (ts?.[i]?.score ?? -1);
  const order = [...oItems.keys()].sort((x, y) => { const a = keyOf(x), b = keyOf(y); return typeof a === "string" ? b.localeCompare(a) : b - a; }).filter(i => { const it = oItems[i]; if (it.error) return true; if ($("#o-only-new").checked && !it.is_new) return false; if ($("#o-only-official").checked && !(it.official || oJudged?.[i]?.kind?.choice === "公的機関の発表" || oJudged?.[i]?.kind?.choice === "報道")) return false; if ($("#o-only-check").checked && !needsCheck(it, oJudged?.[i])) return false; if (flt.length) { const t = `${it.title} ${it.text} ${it.source}`.toLowerCase(); if (!flt.some(f => t.includes(f.toLowerCase()))) return false; } return true; });
  let h = `<p class="muted small">表示 ${order.filter(i => !oItems[i].error).length} 件</p>`; const ny = (a, name, alert) => a ? `<span class="flag ${a.noul ? (alert ? "alert" : "on") : ""}" title="p=${a.p_yes.toFixed(2)}">${name} ${a.noul ? "✓" : "—"}</span>` : "";
  for (const i of order) { const it = oItems[i]; if (it.error) { h += `<div class="item"><div class="meta">#${i} ${it.source} — 取得失敗: ${esc(it.error).slice(0, 120)}</div></div>`; continue; } const j = oJudged?.[i], t = ts?.[i];
    h += `<div class="item ${it.is_new ? "new" : ""}" data-i="${i}"><div><div class="meta">#${i} ${it.official ? "🏛 " : ""}${esc(it.source)}${it.is_new ? " 🆕" : ""} ${(it.time || "").slice(0, 16)}${oClusters && oClusters[i] != null ? ` <span class="pill">群 ${oClusters[i]}</span>` : ""}${it.query && it.query !== $("#o-q").value ? ` <span class="pill">${esc(it.query)}</span>` : ""}${it.elevation_m != null ? ` <span class="pill">標高 ${it.elevation_m.toFixed(0)}m</span>` : ""}</div><div class="ttl">${hl(it.title || "")}</div><div class="txt">${hl(it.text || "")}</div>${j ? `<div class="jv">${j.kind ? `<span class="flag on">${esc(j.kind.choice)} <span class="muted">${pc(j.kind.confidence)}</span></span>` : ""}${j.urgency ? `<span class="flag ${j.urgency.score >= 3.5 ? "alert" : ""}">緊急 ${j.urgency.score.toFixed(1)}/5</span>` : ""}${ny(j.has_specifics, "具体")}${ny(j.asks_spread, "拡散依頼", true)}${j.supported ? `<span class="flag ${contra(j) ? "alert" : j.supported.noul ? "on" : ""}" title="p=${j.supported.p_yes.toFixed(2)}">根拠と整合 ${j.supported.noul ? "✓" : "✗"}</span>` : ""}${ny(j.relevant, "関連")}</div>` : ""}</div>`;
    h += `<div class="trust">${t ? `<span class="muted small">信頼性</span><b class="${t.score >= 0.7 ? "ok" : t.score < 0.4 ? "bad" : ""}">${(t.score * 100).toFixed(0)}</b><div class="bar"><i style="width:${t.score * 100}%"></i></div><details><summary class="small">内訳</summary><div class="small muted" style="text-align:left">${Object.entries(t.parts).map(([k, v]) => `${WN[k]} ${v.toFixed(2)}`).join("<br>")}</div></details>` : ""}</div>`;
    h += `<div class="act"><a href="${esc(it.url)}" target="_blank" rel="noopener"><button class="small">出典を開く</button></a> <button class="small o-addctx" data-i="${i}" title="この情報を根拠（context）に追加">＋根拠に</button> <button class="small o-more" data-i="${i}">全文</button>${it.lang && it.lang !== "ja" && it.lang !== "japanese" || (/[a-zA-Z]{4,}/.test(it.text || "") && !/[\u3040-\u30ff\u4e00-\u9fff]/.test(it.text || "")) ? `<button class="small o-tr" data-i="${i}" title="MyMemory 公開 API（1 日 5,000 文字）">日本語に</button>` : ""} <span class="muted small">人手ラベル:</span> <select class="o-lab" data-i="${i}"><option value="">種類</option>${["公的機関の発表", "報道", "一般の投稿・目撃", "意見・感想", "宣伝・無関係"].map(k => `<option ${oLabels[i]?.kind === k ? "selected" : ""}>${k}</option>`).join("")}</select> <select class="o-lab-t" data-i="${i}"><option value="">信頼</option>${["高", "中", "低"].map(k => `<option ${oLabels[i]?.trust === k ? "selected" : ""}>${k}</option>`).join("")}</select></div></div>`; }
  $("#o-out").innerHTML = h; $$(".o-addctx").forEach(b => b.onclick = () => { const it = oItems[b.dataset.i]; const line = `${it.title}: ${(it.text || "").slice(0, 200)}`; $("#o-ctx").value = [...oCtx().filter(x => x !== line), line].join("\n"); status("根拠に追加しました（「JEV で整理・照合し直す」で反映）"); }); $$(".o-more").forEach(b => b.onclick = () => b.closest(".item").classList.toggle("open")); $$(".o-tr").forEach(b => b.onclick = async () => { const it = oItems[b.dataset.i]; b.disabled = true; const t = await translate(`${it.title}. ${(it.text || "").slice(0, 400)}`, "ja"); if (t) { it.text_ja = t; b.closest(".item").querySelector(".txt").innerHTML += `<div class="small" style="border-left:2px solid var(--acc);padding-left:6px;margin-top:4px">${esc(t)}</div>`; } else { b.disabled = false; status("翻訳できませんでした（1 日の上限か通信）"); } }); $$(".o-lab").forEach(sel => sel.onchange = () => { (oLabels[sel.dataset.i] ??= {}).kind = sel.value; }); $$(".o-lab-t").forEach(sel => sel.onchange = () => { (oLabels[sel.dataset.i] ??= {}).trust = sel.value; }); }
const judgedPlain = () => oJudged?.map(j => j && Object.fromEntries(Object.entries(j).filter(([k]) => k !== "_ms").map(([k, a]) => [k, { label: lab(a), score: a.score, p_yes: a.p_yes, confidence: a.confidence }])));
function labelItems() { const q = $("#o-q").value; const out = []; oItems.forEach((it, i) => { const L = oLabels[i]; if (it.error || !L || (!L.kind && !L.trust)) return; const qs = [], gold = {}; if (L.kind) { qs.push(OSINT_QUESTIONS(q)[1]); gold.kind = L.kind; } if (L.trust) { qs.push({ type: "score", id: "trust", instructions: "この情報の信頼性", levels: ["低", "中", "高"] }); gold.trust = L.trust; } if (qs.length) out.push({ id: `osint-${Date.now()}-${i}`, family: "osint_ja", split: "in_domain", state: `${it.title}\n${it.text}`, context: oGeo.slice(0, 3), meta: { query: q, source: it.source, url: it.url, time: it.time }, questions: qs, gold }); }); return out; }
$("#o-pack").onclick = () => download(`evidence-${Date.now()}.json`, JSON.stringify({ version: VERSION, ...evidencePack($("#o-q").value, oItems, judgedPlain()), geo_context: oGeo, context_used: oCtx(), clusters: oClusters, trust_weights: W, human_labels: oLabels }, null, 1));
$("#o-csv").onclick = () => { const cell = v => `"${String(v ?? "").replace(/"/g, '""')}"`; const ts = oJudged ? oItems.map((it, i) => trustScore(it, oJudged[i], W)) : null; download("osint.csv", "﻿" + ["i,source,title,text,time,url,fetched_at,is_new,cluster,elevation_m,trust,relevant,kind,urgency,has_specifics,asks_spread,supported,needs_check,label_kind,label_trust"].concat(oItems.map((it, i) => { const j = oJudged?.[i]; return [i, it.source, it.title, it.text, it.time, it.url, it.fetched_at, it.is_new ? 1 : 0, oClusters?.[i], it.elevation_m, ts?.[i]?.score?.toFixed(3), j?.relevant?.p_yes?.toFixed(2), j?.kind?.choice, j?.urgency?.score?.toFixed(2), j?.has_specifics?.p_yes?.toFixed(2), j?.asks_spread?.p_yes?.toFixed(2), j?.supported?.p_yes?.toFixed(2), needsCheck(it, j) ? 1 : 0, oLabels[i]?.kind, oLabels[i]?.trust].map(cell).join(","); })).join("\n"), "text/csv"); };
$("#o-md").onclick = () => { const ts = oJudged ? oItems.map((it, i) => trustScore(it, oJudged[i], W)) : null; download(`report-${Date.now()}.md`, markdownReport($("#o-q").value, oItems, oJudged, ts, oClusters, oGeo), "text/markdown"); };
$("#o-note").onclick = async () => { const o = curOpts(); await saveNote({ kind: "osint", name: `OSINT: ${$("#o-q").value}`, model: jev.name, method: o.method, pool: o.pool, T: o.T, cosScale: o.cosScale, query: $("#o-q").value, n_items: oItems.length, trust_weights: { ...W }, items: evidencePack($("#o-q").value, oItems, null).items, judged: judgedPlain(), human_labels: oLabels }); status("保存しました"); };
$("#o-label").onclick = () => { const lines = labelItems().map(x => JSON.stringify(x)); if (!lines.length) return status("ラベルを付けた行がありません（各カードの「人手ラベル」で種類か信頼を選ぶ）"); download(`osint_ja-${Date.now()}.jsonl`, lines.join("\n") + "\n", "application/jsonl"); };

/* ================= チャット ================= */
function botSay(html) { const d = document.createElement("div"); d.className = "msg bot"; d.innerHTML = html; $("#chat").appendChild(d); $("#chat").scrollTop = 1e9; }
function meSay(t) { const d = document.createElement("div"); d.className = "msg me"; d.textContent = t; $("#chat").appendChild(d); $("#chat").scrollTop = 1e9; }
let chatCtx = [], chatLast = "";
const chatQs = () => { if ($("#c-mode").value === "play") { const qs = readQuestions(); if (qs.length) return qs; } return OSINT_QUESTIONS($("#o-q").value || "話題").filter(x => x.id !== "supported" || chatCtx.length); };
function explain(a, q) { const c = `<span class="conf ${confCls(a.confidence)}">${pc(a.confidence)}</span>`; const v = a.type === "choice" ? esc(a.choice) : a.type === "score" ? `${esc(a.level)} <span class="muted small">(${a.score.toFixed(1)})</span>` : (a.noul ? "はい" : "いいえ"); return `<div class="ar"><span class="qn">${esc(q?.instructions || a.id)}</span><b>${v}</b>${c}</div>`; }
async function chatHandle(text) {
  if (text === "/help") return botSay("使い方：<br>・文章を送る → 質問セットで判断<br>・<code>? 質問文</code> → 直前の文章に はい/いいえ で答える（例: <code>? 返信が必要か</code>）<br>・<code>? 質問文 | 選択肢1 | 選択肢2</code> → 選択式（例: <code>? 担当は | 請求 | 配送</code>）<br>・<code>/ctx 根拠文</code>・<code>/ctx clear</code> → 根拠の追加・削除<br>・<code>/osint 調べたいこと</code> → 収集して信頼性順に要約<br>・<code>/q choice id 質問 | A | B</code> → 質問セットに追加、<code>/qs</code> いまの質問、<code>/clear</code>");
  if (text === "/clear") { $("#chat").innerHTML = ""; return; }
  if (text === "/qs") return botSay("いまの質問：<br>" + chatQs().map(q => `・${esc(q.instructions)} [${q.type}]${q.options ? " {" + q.options.map(esc).join(" | ") + "}" : q.levels ? " {" + q.levels.map(esc).join(" < ") + "}" : ""}`).join("<br>"));
  if (text.startsWith("/ctx")) { const c = text.slice(4).trim(); if (c === "clear") { chatCtx = []; return botSay("根拠を消しました"); } chatCtx.push(c); return botSay(`根拠を追加（${chatCtx.length} 件）`); }
  if (text.startsWith("/preset")) { const id = text.slice(7).trim(); const p = OSINT_PRESETS.find(x => x.id === id) || OSINT_PRESETS.find(x => x.name.includes(id)); if (!p) return botSay("プリセット: " + OSINT_PRESETS.map(x => `<code>${x.id}</code>`).join(" ")); applyPreset(p); return botSay(`プリセット「${esc(p.name)}」を設定。<code>/osint</code> で収集します`); }
  if (text.startsWith("/q ")) { const m = /^\/q\s+(choice|score|noul)\s+(\S+)\s+(.*)$/s.exec(text); if (!m) return botSay("書式: /q choice id 質問 | 選択肢1 | 選択肢2"); const [_, type, id, rest] = m; const parts = rest.split("|").map(s => s.trim()).filter(Boolean); const q = { type, id, instructions: parts[0] }; if (type === "choice") q.options = parts.slice(1); if (type === "score") q.levels = parts.slice(1); if ((type !== "noul") && (q.options || q.levels).length < 2) return botSay("選択肢は 2 つ以上"); const qs = readQuestions().filter(x => x.id !== id); setQuestions([...qs, q]); $("#c-mode").value = "play"; return botSay(`質問 <b>${esc(id)}</b> を追加（計 ${qs.length + 1}）`); }
  if (text.startsWith("/osint")) { const q = text.slice(6).trim() || $("#o-q").value; $("#o-q").value = q; botSay(`「${esc(q)}」を収集中…`); await doCollect(q); if (jev && !oJudged) await doJudge(); const ts = oJudged ? oItems.map((it, i) => trustScore(it, oJudged[i], W)) : null; const ok = oItems.filter(i => !i.error); const top = [...ok.keys()].map(k => oItems.indexOf(ok[k])).sort((x, y) => (ts?.[y]?.score ?? 0) - (ts?.[x]?.score ?? 0)).slice(0, 5); const chk = oJudged ? [...oItems.keys()].filter(i => needsCheck(oItems[i], oJudged[i])) : [];
    return botSay(`${ok.length} 件取得${oJudged ? "・整理済" : ""}。信頼性の高い順:<br>` + top.map(i => `・[${oItems[i].source}] ${esc(oItems[i].title || "")}${ts?.[i] ? ` <span class="pill">${(ts[i].score * 100).toFixed(0)}</span>` : ""}${oJudged?.[i]?.kind ? ` <span class="muted small">${esc(oJudged[i].kind.choice)}</span>` : ""}`).join("<br>") + (chk.length ? `<br><span class="warn">要確認 ${chk.length} 件: ${chk.map(i => "#" + i).join(", ")}</span>` : "") + `<br><span class="muted small">詳細は「情報収集」タブ</span>`); }
  if (!ready()) return;
  if (/^[?？]/.test(text)) { if (!chatLast) return botSay("先に判断したい文章を送ってください（その後に <code>? 質問</code>）"); const parts = text.slice(1).split("|").map(s => s.trim()).filter(Boolean); const q = parts.length >= 3 ? { type: "choice", id: "adhoc", instructions: parts[0], options: parts.slice(1) } : { type: "noul", id: "adhoc", instructions: parts[0] }; const r = await jev.decide(chatLast, [q], chatCtx.length ? chatCtx : null, curOpts()); const a = r.answers[0]; bump(1, r.latency_ms); return botSay(`<div class="meta">「${esc(chatLast.slice(0, 40))}${chatLast.length > 40 ? "…" : ""}」について</div>` + explain(a, q) + `<div class="dist">${a.distribution.labels.map((l, i) => `<span>${esc(l)}</span><div class="bar"><i style="width:${a.distribution.probabilities[i] * 100}%"></i></div><span>${(a.distribution.probabilities[i] * 100).toFixed(0)}%</span>`).join("")}</div>`); }
  chatLast = text; const qs = chatQs(); const r = await jev.decide(text, qs, chatCtx.length ? chatCtx : null, curOpts());
  let h = r.answers.map((a, i) => explain(a, qs[i])).join(""); h += `<div class="meta">${esc(jev.name)} ・ ${r.latency_ms.toFixed(0)} ms ・ 端末内${chatCtx.length ? " ・ 根拠 " + chatCtx.length + " 件" : ""}。続けて「? 質問」で深掘り</div>`; botSay(h); bump(qs.length, r.latency_ms);
}
$("#c-send").onclick = async () => { const t = $("#c-in").value.trim(); if (!t) return; meSay(t); $("#c-in").value = ""; $("#c-send").disabled = true; try { await chatHandle(t); } catch (e) { botSay("エラー: " + esc(e.message)); } $("#c-send").disabled = !jev; };
$("#c-in").onkeydown = e => { if (e.key === "Enter" && !e.shiftKey && !isMobile) { e.preventDefault(); $("#c-send").click(); } }; $("#c-in").oninput = () => { const t = $("#c-in"); t.style.height = "auto"; t.style.height = Math.min(120, t.scrollHeight) + "px"; };
$$(".c-quick").forEach(b => b.onclick = async () => { meSay(b.dataset.q); try { await chatHandle(b.dataset.q); } catch (e) { botSay("エラー: " + esc(e.message)); } });
botSay("JEV チャットです。モデルを読み込んでから文章を送ってください。続けて <code>? 返信が必要か</code> のように聞くと、その文章について はい/いいえ で答えます。<code>/osint 津市 大雨</code> で収集→整理まで実行。");

/* ================= 実験ノート ================= */
async function saveNote(e) { e.id = e.id || `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`; e.time = e.time || new Date().toISOString(); e.device = e.device || navigator.userAgent; e.app_version = VERSION; e.notes = e.notes || ""; await store.expPut(e); return e.id; }
$("#p-note").onclick = async () => { if (!last) return; const o = curOpts(); await saveNote({ kind: "decide", name: prompt("実験名", `${jev.name} ${optsLabel(o)}`) || "decide", model: jev.name, method: o.method, pool: o.pool, T: o.T, cosScale: o.cosScale, input: last.input, n_tokens: last.n_tokens, timing: last.timing, answers: last.answers.map(a => ({ id: a.id, type: a.type, label: lab(a), confidence: a.confidence, labels: a.distribution.labels, probabilities: a.distribution.probabilities })) }); status("保存しました"); };
async function refreshNotes() { const es = (await store.expAll()).sort((x, y) => y.time.localeCompare(x.time)); for (const id of ["#n-a", "#n-b"]) $(id).innerHTML = es.filter(e => e.kind === "batch").map(e => `<option value="${e.id}">${esc(e.name)}</option>`).join(""); if (!es.length) { $("#n-list").innerHTML = '<p class="muted">まだ記録がありません。「文章を判断」「バッチ評価」「情報収集」などの「実験ノートに保存」で増えます。</p>'; return; }
  $("#n-list").innerHTML = "<table><tr><th>時刻</th><th>種別</th><th>名前</th><th>モデル</th><th>設定</th><th>データ / 入力</th><th>精度</th><th>Brier</th><th>ECE</th><th>p50</th><th>メモ</th><th></th></tr>" + es.map(e => `<tr><td class="small">${e.time.replace("T", " ").slice(0, 16)}</td><td>${e.kind}</td><td>${esc(e.name)}</td><td>${esc(e.model || "")}${e.head ? " <span class='tag'>" + e.head + "</span>" : ""}</td><td class="small">${e.method ? optsLabel(e) : ""}</td><td class="small">${esc(e.dataset || (e.input?.state || e.state || e.query || "").slice(0, 40))}</td><td>${e.accuracy != null ? (e.accuracy * 100).toFixed(1) + "%" + (e.accuracy_ci95 ? `<br><span class="muted small">${(e.accuracy_ci95[0] * 100).toFixed(0)}–${(e.accuracy_ci95[1] * 100).toFixed(0)}</span>` : "") : (e.after?.val ? `${(e.before.val.acc * 100).toFixed(0)}→${(e.after.val.acc * 100).toFixed(0)}%` : "")}</td><td>${e.brier != null ? e.brier.toFixed(3) : ""}</td><td>${e.ece != null ? e.ece.toFixed(3) : ""}</td><td>${e.latency_p50_ms != null ? e.latency_p50_ms.toFixed(0) : (e.timing ? e.timing.total_ms.toFixed(0) : "")}</td><td><input data-id="${e.id}" class="n-memo" value="${esc(e.notes || "")}" placeholder="メモ"></td><td><button data-id="${e.id}" class="n-dl">JSON</button> <button data-id="${e.id}" class="n-del">✕</button></td></tr>`).join("") + "</table>";
  $$(".n-del").forEach(b => b.onclick = async () => { await store.expDel(b.dataset.id); refreshNotes(); }); $$(".n-dl").forEach(b => b.onclick = async () => { const e = (await store.expAll()).find(x => x.id === b.dataset.id); download(`exp-${e.id}.json`, JSON.stringify(e, null, 1)); }); $$(".n-memo").forEach(i => i.onchange = async () => { const e = (await store.expAll()).find(x => x.id === i.dataset.id); e.notes = i.value; await store.expPut(e); }); }
$("#n-table").onclick = async () => { const es = (await store.expAll()).filter(e => e.kind === "batch").sort((x, y) => x.time.localeCompare(y.time)); if (!es.length) return status("バッチ評価の記録がありません"); const md = ["| モデル | 設定 | データ | n | 精度 (95%CI) | 多数決 | Brier | ECE | p50 ms | 端末 |", "|---|---|---|---|---|---|---|---|---|---|", ...es.map(e => `| ${e.model}${e.head === "custom" ? " (端末学習)" : ""} | ${optsLabel(e)}${e.use_context === false ? " ctx無" : ""} | ${e.dataset} | ${e.n_questions} | ${(e.accuracy * 100).toFixed(1)}%${e.accuracy_ci95 ? ` (${(e.accuracy_ci95[0] * 100).toFixed(0)}–${(e.accuracy_ci95[1] * 100).toFixed(0)})` : ""} | ${e.baseline_majority != null ? (e.baseline_majority * 100).toFixed(1) + "%" : ""} | ${e.brier.toFixed(3)} | ${e.ece.toFixed(3)} | ${e.latency_p50_ms?.toFixed(0) ?? ""} | ${/Android|iPhone/i.test(e.device || "") ? "スマホ" : "PC"} |`)].join("\n"); $("#n-md").classList.remove("hidden"); $("#n-md").value = md; try { await navigator.clipboard.writeText(md); status("Markdown 表をクリップボードにコピーしました"); } catch { } };
$("#n-cmp").onclick = async () => { const es = await store.expAll(); const a = es.find(e => e.id === $("#n-a").value), b = es.find(e => e.id === $("#n-b").value); if (!a || !b) return; const fams = [...new Set([...Object.keys(a.per_family || {}), ...Object.keys(b.per_family || {})])]; $("#n-cmp-out").innerHTML = `<table><tr><th></th><th>${esc(a.name)}</th><th>${esc(b.name)}</th><th>差</th></tr><tr><td>精度</td><td>${(a.accuracy * 100).toFixed(1)}%</td><td>${(b.accuracy * 100).toFixed(1)}%</td><td>${((b.accuracy - a.accuracy) * 100).toFixed(1)}</td></tr><tr><td>Brier</td><td>${a.brier.toFixed(3)}</td><td>${b.brier.toFixed(3)}</td><td>${(b.brier - a.brier).toFixed(3)}</td></tr><tr><td>ECE</td><td>${a.ece.toFixed(3)}</td><td>${b.ece.toFixed(3)}</td><td>${(b.ece - a.ece).toFixed(3)}</td></tr>${fams.map(f => `<tr><td>${esc(f)}</td><td>${a.per_family?.[f] ? (a.per_family[f].accuracy * 100).toFixed(1) + "%" : "—"}</td><td>${b.per_family?.[f] ? (b.per_family[f].accuracy * 100).toFixed(1) + "%" : "—"}</td><td>${a.per_family?.[f] && b.per_family?.[f] ? ((b.per_family[f].accuracy - a.per_family[f].accuracy) * 100).toFixed(1) : ""}</td></tr>`).join("")}</table>`; };
$("#n-csv").onclick = async () => { const es = await store.expAll(); const cols = ["time", "kind", "name", "model", "head", "method", "pool", "T", "cosScale", "dataset", "n_states", "n_questions", "use_context", "backend", "accuracy", "accuracy_ci95", "baseline_majority", "brier", "ece", "latency_p50_ms", "latency_p95_ms", "app_version", "notes"]; download("experiments.csv", "﻿" + [cols.join(",")].concat(es.map(e => cols.map(c => `"${String(e[c] ?? "").replace(/"/g, '""')}"`).join(","))).join("\n"), "text/csv"); };
$("#n-json").onclick = async () => download(`experiments-${Date.now()}.json`, JSON.stringify(await store.expAll(), null, 1));
$("#n-import").onchange = async e => { const f = e.target.files[0]; if (!f) return; const es = JSON.parse(await f.text()); for (const x of (Array.isArray(es) ? es : [es])) await store.expPut(x); refreshNotes(); };
$("#n-clear").onclick = async () => { if (!confirm("実験ノートを全削除しますか？")) return; for (const e of await store.expAll()) await store.expDel(e.id); refreshNotes(); };

/* ================= モデル ================= */
async function refreshModels() { const all = await listAllModels(); $("#m-list").innerHTML = "<table><tr><th>名前</th><th>種類</th><th>HF / backbone</th><th>言語</th><th>サイズ</th><th>どこで</th><th>備考</th></tr>" + all.map(m => `<tr><td>${esc(m.name)}</td><td>${m.kind}</td><td class="small">${esc(m.hf_id || m.backbone || "")}</td><td>${m.language || ""}</td><td>${m.size_mb ? m.size_mb + " MB" : ""}</td><td class="small">${m.kind === "jev_ja" ? "スマホ・PC" : "PC ブラウザ"}</td><td class="small">${esc(m.note || "")}</td></tr>`).join("") + "</table>"; }
$("#m-search").addEventListener("keydown", e => { if (e.key === "Enter") $("#m-search-run").click(); });
$("#m-search-run").onclick = async () => { const q = $("#m-search").value.trim() || "jev"; $("#m-search-out").innerHTML = "検索中…"; try { const r = await apiFetch("hf", `https://huggingface.co/api/models?search=${encodeURIComponent(q)}&sort=lastModified&direction=-1&limit=40`);
  $("#m-search-out").innerHTML = "<table><tr><th>モデル</th><th>更新</th><th>DL</th><th>❤</th><th>タグ</th><th>ブラウザ</th><th></th></tr>" + r.map(m => { const tags = m.tags || []; const web = tags.includes("transformers.js") || tags.includes("onnx"); const lic = tags.find(t => t.startsWith("license:"))?.slice(8) || ""; const lang = tags.filter(t => ["ja", "en", "multilingual"].includes(t)).join("/"); return `<tr><td><a href="https://huggingface.co/${m.id}" target="_blank" rel="noopener">${esc(m.id)}</a></td><td class="small">${(m.lastModified || "").slice(0, 10)}</td><td>${m.downloads ?? ""}</td><td>${m.likes ?? ""}</td><td class="small">${lic} ${lang} ${tags.includes("gguf") ? "gguf" : ""} ${tags.includes("safetensors") ? "safetensors" : ""}</td><td>${web ? "✅ onnx" : "PC 用"}</td><td>${web ? `<button class="small m-fill" data-id="${m.id}">JSON に入れる</button>` : ""}</td></tr>`; }).join("") + "</table><p class='muted small'>「ブラウザ」列が ✅ でも入力形式（open-jev 形か、cross-encoder か、Laya 形か、独自か）はモデルカードで確認が必要。open-jev 形なら kind: open-jev-onnx で動く。</p>";
  $$(".m-fill").forEach(b => b.onclick = () => { $("#m-json").value = JSON.stringify({ name: b.dataset.id.split("/").pop().replace(/[^a-z0-9]+/gi, "_").toLowerCase(), kind: "open-jev-onnx", hf_id: b.dataset.id, dtype: "q4", dtype_webgpu: "q4f16", language: "en", note: "入力形式を要確認" }, null, 1); }); } catch (e) { $("#m-search-out").textContent = "検索失敗: " + e.message; } };
$("#m-add").onclick = async () => { let e; try { e = JSON.parse($("#m-json").value); } catch (err) { return alert("JSON エラー: " + err.message); } if (!e.name || !e.kind) return alert("name, kind が必要"); if (!["open-jev-onnx", "crossenc", "laya"].includes(e.kind)) return alert("kind は open-jev-onnx / crossenc / laya（Jev 級のみ）"); if (e.kind === "open-jev-onnx" && !e.hf_id) return alert("hf_id が必要"); const custom = (await store.get("registry:custom")) || []; await store.put("registry:custom", [...custom.filter(x => x.name !== e.name), e]); await loadIndex(); refreshModels(); status(`${e.name} を追加しました。上のモデル欄から読み込めます`); };
$("#m-clear").onclick = async () => { await store.del("registry:custom"); await loadIndex(); refreshModels(); };

/* ================= 設定 ================= */
async function refreshSettings() { const ks = await store.keys(); const by = {}; for (const k of ks) { if (!k.includes("/")) continue; const [m] = k.split("/"); by[m] = (by[m] || 0) + ((await store.get(k))?.byteLength || 0); } $("#s-models").innerHTML = Object.keys(by).length ? "<table><tr><th>モデル</th><th>サイズ</th><th></th></tr>" + Object.entries(by).map(([m, b]) => `<tr><td>${esc(m)}</td><td>${(b / 1e6).toFixed(1)} MB</td><td><button data-m="${m}" class="s-del">削除</button></td></tr>`).join("") + "</table>" : "保存されたモデルはありません（open-jev-onnx はブラウザのキャッシュに入ります）"; $$(".s-del").forEach(b => b.onclick = async () => { for (const k of await store.keys()) if (k.startsWith(b.dataset.m + "/")) await store.del(k); refreshSettings(); markStored(); storageInfo(); });
  const qs = quotaStatus(); const cnt = await store.cacheCount().catch(() => 0); $("#s-quota").innerHTML = `<p class="hint">すべて無料の公開 API。各 API の無料枠より少なめの上限を端末内で数え、超えたら呼ばずにスキップする。同じ URL の応答はキャッシュ（右列の TTL）し、キャッシュ命中は枠を消費しない。現在のキャッシュ ${cnt} 件。</p><div class="tw"><table><tr><th>API</th><th>今日</th><th>1 時間</th><th>1 分</th><th>文字/日</th><th>間隔</th><th>キャッシュ</th><th>命中</th><th>無料枠</th></tr>${qs.map(x => { const warn = (u, l) => l && u >= l * 0.8 ? "warn" : ""; return `<tr><td>${x.api}</td><td class="${warn(x.used_day, x.limit_day)}">${x.used_day}${x.limit_day ? " / " + x.limit_day : ""}</td><td class="${warn(x.used_hour, x.limit_hour)}">${x.limit_hour ? x.used_hour + " / " + x.limit_hour : ""}</td><td>${x.limit_min ? x.used_min + " / " + x.limit_min : ""}</td><td class="${warn(x.chars, x.limit_chars)}">${x.limit_chars ? x.chars + " / " + x.limit_chars : ""}</td><td>${x.interval ? (x.interval / 1000).toFixed(1) + " s" : ""}</td><td>${x.ttl ? (x.ttl >= 86400 ? (x.ttl / 86400) + " 日" : x.ttl >= 3600 ? (x.ttl / 3600) + " 時間" : (x.ttl / 60) + " 分") : "なし"}</td><td>${x.cache_hits}</td><td class="small muted">${esc(x.note)}</td></tr>`; }).join("")}</table></div>`;
  $("#s-env").innerHTML = `<span>UA</span><span class="small">${navigator.userAgent}</span><span>WebGPU</span><span>${navigator.gpu ? "あり" : "なし（WASM）"}</span><span>CPU</span><span>${navigator.hardwareConcurrency ?? "?"} コア</span><span>メモリ</span><span>${navigator.deviceMemory ? navigator.deviceMemory + " GB" : "?"}</span><span>Service Worker</span><span>${navigator.serviceWorker?.controller ? "制御中" : "未"}</span><span>オンライン</span><span>${navigator.onLine ? "はい" : "いいえ"}</span><span>アプリ</span><span>${VERSION}</span>`; storageInfo(); }
$("#s-cache-clear").onclick = async () => { await cacheClear(); refreshSettings(); status("キャッシュを消しました（次回の取得は無料枠を消費します）"); }; $("#s-quota-reset").onclick = () => { if (confirm("使用回数の記録をリセットしますか？（実際の無料枠はリセットされません。日付が変わると自動で戻ります）")) { quotaReset(); refreshSettings(); } };
$("#s-persist").onclick = async () => { const ok = await navigator.storage.persist?.(); status(ok ? "永続化されました" : "許可されませんでした（ホーム画面に追加すると通ることがあります）"); storageInfo(); };
$("#s-clear").onclick = async () => { if (!confirm("保存したモデルをすべて削除しますか？")) return; for (const k of await store.keys()) if (k.includes("/")) await store.del(k); refreshSettings(); markStored(); };
$("#s-update").onclick = async () => { const r = await navigator.serviceWorker?.getRegistration(); await r?.update(); const ks = await caches.keys(); for (const k of ks) if (k.startsWith("jev-lab-app")) await caches.delete(k); location.reload(true); };
$("#s-backup").onclick = async () => { const data = { version: VERSION, time: new Date().toISOString(), qsets: await store.get("qsets"), registry_custom: await store.get("registry:custom"), trust_weights: W, queries: JSON.parse(localStorage.getItem("jev.queries") || "[]"), experiments: await store.expAll() }; download(`jev-lab-backup-${Date.now()}.json`, JSON.stringify(data, null, 1)); };
$("#s-restore").onchange = async e => { const f = e.target.files[0]; if (!f) return; const d = JSON.parse(await f.text()); if (d.qsets) await store.put("qsets", d.qsets); if (d.registry_custom) await store.put("registry:custom", d.registry_custom); if (d.queries) localStorage.setItem("jev.queries", JSON.stringify(d.queries)); for (const x of (d.experiments || [])) await store.expPut(x); refreshQSets(); savedQueries(); await loadIndex(); status("復元しました"); };
$("#s-dark").onchange = () => { document.documentElement.dataset.theme = $("#s-dark").checked ? "dark" : "light"; try { localStorage.setItem("jev.theme", document.documentElement.dataset.theme); } catch { } };
$("#s-big").onchange = () => { document.body.style.fontSize = $("#s-big").checked ? "17px" : ""; try { localStorage.setItem("jev.big", $("#s-big").checked ? "1" : ""); } catch { } };
try { const th = localStorage.getItem("jev.theme"); if (th) { document.documentElement.dataset.theme = th; $("#s-dark").checked = th === "dark"; } if (localStorage.getItem("jev.big")) { $("#s-big").checked = true; document.body.style.fontSize = "17px"; } } catch { }
