/* ================= ツール箱 ================= */
$("#tool-nav").innerHTML = $$(".tool").map(t => `<span class="chip" data-t="${t.id}">${esc(t.querySelector("h2").textContent)}</span>`).join(""); $$("#tool-nav .chip").forEach(c => c.onclick = () => document.getElementById(c.dataset.t).scrollIntoView({ behavior: "smooth", block: "start" }));
/* --- dork --- */
DORK_LIBRARY.forEach((d, i) => { const o = document.createElement("option"); o.value = i; o.textContent = `${d.cat}: ${d.name}`; $("#d-lib").appendChild(o); });
$("#d-ops").innerHTML = "<table><tr><th>演算子</th><th>意味</th><th>例</th></tr>" + DORK_OPERATORS.map(([a, b, c]) => `<tr><td><code>${esc(a)}</code></td><td>${esc(b)}</td><td class="small">${esc(c)}</td></tr>`).join("") + "</table>";
const dorkExpr = () => { const r = buildDorks({ q: $("#d-q").value, site: $("#d-site").value, filetype: $("#d-ft").value, intitle: $("#d-title").value, inurl: $("#d-url").value, exclude: $("#d-ex").value, after: $("#d-after").value, before: $("#d-before").value, exact: $("#d-exact").checked }); let q = r.query; const v = id => ($("#" + id)?.value || "").trim(); if (v("d-text")) q += ` intext:"${v("d-text")}"`; const or = v("d-or").split(",").map(x => x.trim()).filter(Boolean); if (or.length) q += ` (${or.join(" OR ")})`; if (v("d-range")) q += " " + v("d-range");
  if (v("d-allintitle")) q = `allintitle:${v("d-allintitle")} ` + q; if (v("d-anchor")) q += ` inanchor:"${v("d-anchor")}"`; if (v("d-ar-a") && v("d-ar-b")) { const [b, n] = v("d-ar-b").split(",").map(x => x.trim()); q += ` "${v("d-ar-a")}" AROUND(${n || 5}) "${b}"`; } if (v("d-related")) q += ` related:${v("d-related")}`; if (v("d-imgsize")) q += ` imagesize:${v("d-imgsize")}`; if (v("d-source")) q += ` source:${v("d-source")}`; if (v("d-loc")) q += ` loc:${v("d-loc")}`; if (v("d-ip")) q += ` ip:${v("d-ip")}`; if (v("d-contains")) q += ` contains:${v("d-contains")}`; return q.trim(); };
$("#d-lib").onchange = () => { const d = DORK_LIBRARY[$("#d-lib").value]; if (!d) return; const q = $("#d-q").value || $("#o-q").value.split(/[,、]/)[0] || "{q}"; $("#d-expr").value = buildFromLibrary(d, q, domainOf(q)); showDorkLinks(); };
function showDorkLinks() { const q = $("#d-expr").value.trim(); if (!q) return; const r = buildDorks({ q }); const bing = q.replace(/\bfiletype:/g, "filetype:").replace(/\bintext:/g, "inbody:").replace(/\s(after|before):\S+/g, ""), ddg = q.replace(/\s(after|before|related|imagesize|source|loc|ip|contains):\S+/g, "").replace(/AROUND\(\d+\)/g, ""), yandex = q.replace(/\bfiletype:/g, "mime:").replace(/\bintext:/g, "").replace(/\s(after|before|related|imagesize|source|loc|ip|contains):\S+/g, "");
  const note = [/\b(related|imagesize|source|AROUND)/.test(q) ? "related / imagesize / source / AROUND は Google 専用" : "", /\b(loc|ip|contains):/.test(q) ? "loc / ip / contains は Bing 専用（Google の式では無視される）" : ""].filter(Boolean).join("。");
  $("#d-out").innerHTML = `<p>${r.links.filter(l => !["Wikipedia", "Bing", "DuckDuckGo"].includes(l.name)).map(l => `<a href="${l.url}" target="_blank" rel="noopener"><button class="small">${l.name}</button></a>`).join(" ")} <a href="https://www.bing.com/search?q=${encodeURIComponent(bing)}" target="_blank" rel="noopener"><button class="small">Bing</button></a> <a href="https://duckduckgo.com/?q=${encodeURIComponent(ddg)}" target="_blank" rel="noopener"><button class="small">DuckDuckGo</button></a> <a href="https://yandex.com/search/?text=${encodeURIComponent(yandex)}" target="_blank" rel="noopener"><button class="small">Yandex</button></a> <a href="https://www.startpage.com/do/search?q=${encodeURIComponent(q)}" target="_blank" rel="noopener"><button class="small">Startpage</button></a> <a href="https://search.brave.com/search?q=${encodeURIComponent(q)}" target="_blank" rel="noopener"><button class="small">Brave</button></a></p><p class="hint">Bing 用: <code>${esc(bing)}</code>${note ? "<br>" + note : ""}</p>`; }
$("#d-build").onclick = () => { $("#d-expr").value = dorkExpr(); showDorkLinks(); }; $("#d-open").onclick = showDorkLinks; $("#d-copy").onclick = () => navigator.clipboard?.writeText($("#d-expr").value);
/* --- 画像 --- */
$("#t-exif").onchange = async e => { const f = e.target.files[0]; if (!f) return; const x = await readExif(f); $("#t-exif-out").innerHTML = "<table>" + Object.entries(x).map(([k, v]) => `<tr><td>${esc(k)}</td><td class="small">${k === "map" ? `<a href="${v}" target="_blank" rel="noopener">${v}</a>` : esc(String(v))}</td></tr>`).join("") + "</table>" + (x.lat != null ? `<p><button class="small" id="t-exif-ctx">→ 根拠に追加（撮影地点の座標）</button> <button class="small" id="t-exif-recon">→ 座標を調査</button></p>` : "") + `<p class="small muted">ELA を計算中…</p>`; const b = $("#t-exif-ctx"); if (b) b.onclick = () => { $("#o-ctx").value = [...oCtx(), `画像 ${x.file}: 撮影 ${x.DateTimeOriginal || x.DateTime || "?"}, 位置 ${x.lat}, ${x.lon}, 機種 ${x.Make || ""} ${x.Model || ""}`].join("\n"); status("根拠に追加しました"); }; const b2 = $("#t-exif-recon"); if (b2) b2.onclick = () => { $("#r-q").value = `${x.lat},${x.lon}`; showTab("recon"); $("#r-run").click(); };
  try { const r = await ela(f); const c = $("#t-ela"); c.width = r.width; c.height = r.height; c.getContext("2d").drawImage(r.canvas, 0, 0); c.classList.remove("hidden"); $("#t-exif-out").querySelector("p.small.muted").innerHTML = `ELA（最大差分 ${r.max}）: ${esc(r.note)}`; } catch (err) { $("#t-exif-out").querySelector("p.small.muted").textContent = "ELA 不可: " + err.message; } };
$("#t-img-run").onclick = () => { const u = $("#t-img").value.trim(); if (!u) return; $("#t-img-out").innerHTML = reverseImageLinks(u).map(l => `<a href="${l.url}" target="_blank" rel="noopener"><button class="small">${l.name}</button></a>`).join(" "); };
/* --- 文書メタデータ --- */
