$("#c-hash").onclick = async () => { const t = $("#c-input").value; $("#c-output").value = `SHA-256: ${await hashText(t, "SHA-256")}\nSHA-1:   ${await hashText(t, "SHA-1")}`; };
/* --- ファイルハッシュ --- */
$("#t-file").onchange = async e => { const f = e.target.files[0]; if (!f) return; const h = await hashFile(f); const h1 = await hashFile(f, "SHA-1"); $("#t-file-out").innerHTML = `<table><tr><td>ファイル</td><td class="small">${esc(f.name)}（${(f.size / 1e6).toFixed(2)} MB）</td></tr><tr><td>SHA-256</td><td class="small"><code>${h}</code></td></tr><tr><td>SHA-1</td><td class="small"><code>${h1}</code></td></tr></table><p><a href="https://www.virustotal.com/gui/search/${h}" target="_blank" rel="noopener"><button class="small">VirusTotal で検索</button></a> <a href="https://bazaar.abuse.ch/browse.php?search=sha256%3A${h}" target="_blank" rel="noopener"><button class="small">MalwareBazaar</button></a> <a href="https://www.hybrid-analysis.com/search?query=${h}" target="_blank" rel="noopener"><button class="small">Hybrid Analysis</button></a></p><p class="hint">ハッシュだけを検索する（ファイルは送らない）。未知のファイルは「該当なし」になる。</p>`; };
/* --- 太陽 --- */
$("#s-dt").value = new Date(Date.now() - new Date().getTimezoneOffset() * 6e4).toISOString().slice(0, 16);
$("#s-run").onclick = () => { const [la, lo] = $("#s-ll").value.split(",").map(Number); if (isNaN(la) || isNaN(lo)) return status("緯度, 経度 を入れてください"); const d = new Date($("#s-dt").value); const p = sunPosition(la, lo, d); const dir = ["北", "北東", "東", "南東", "南", "南西", "西", "北西"][Math.round(p.azimuth / 45) % 8]; $("#s-out").innerHTML = `<table><tr><td>太陽の方位</td><td>${p.azimuth.toFixed(1)}°（${dir}）</td></tr><tr><td>太陽の高度</td><td>${p.altitude.toFixed(1)}°${p.altitude <= 0 ? "（地平線下＝夜）" : ""}</td></tr><tr><td>影の向き</td><td>${p.altitude > 0 ? ((p.azimuth + 180) % 360).toFixed(0) + "°（" + ["北", "北東", "東", "南東", "南", "南西", "西", "北西"][Math.round(((p.azimuth + 180) % 360) / 45) % 8] + "）" : "—"}</td></tr><tr><td>影の長さ / 高さ</td><td>${p.shadow_ratio != null ? p.shadow_ratio.toFixed(2) + " 倍" : "—"}</td></tr></table><p class="hint">写真の影がこの向き・長さと合わなければ、撮影時刻か場所が主張と違う可能性。</p>`; };
/* --- 電話 --- */
$("#ph-run").onclick = () => { const p = parsePhone($("#ph-q").value); $("#ph-out").innerHTML = "<table>" + Object.entries(p).filter(([k]) => k !== "links").map(([k, v]) => `<tr><td>${esc(k)}</td><td class="small">${esc(String(v))}</td></tr>`).join("") + "</table>" + (p.links ? "<p>" + p.links.map(l => `<a href="${l.url}" target="_blank" rel="noopener"><button class="small">${esc(l.name)}</button></a>`).join(" ") + "</p>" : ""); };
