/* --- OpSec --- */
$("#fp-run").onclick = () => { $("#fp-out").innerHTML = Object.entries(fingerprint()).map(([k, v]) => `<span>${esc(k)}</span><span class="small">${esc(String(v))}</span>`).join(""); };
$("#pw-run").onclick = async () => { const pw = $("#pw-q").value; if (!pw) return; try { const r = await pwnedPassword(pw); $("#pw-out").innerHTML = r.count ? `<p class="bad">⚠️ 既知の漏えいデータに <b>${r.count.toLocaleString()}</b> 回出現。このパスワードは使わない。</p>` : `<p class="ok">✅ 既知の漏えいデータには見つからなかった（送ったのは SHA-1 の先頭 5 文字 ${r.prefix} だけ）</p>`; } catch (e) { $("#pw-out").textContent = "確認失敗: " + e.message; } $("#pw-q").value = ""; };
$("#learn-links").innerHTML = FRAMEWORK.filter(c => ["トレーニング", "ドキュメント化 / 証拠保全", "ツール（汎用）", "OpSec（運用セキュリティ）"].includes(c.cat)).map(c => `<p><b>${esc(c.cat)}</b> <span class="muted small">${esc(c.note || "")}</span><br>${(c.tools || []).filter(t => t.kind === "link").map(t => `<a href="${t.url.replace("{q}", "")}" target="_blank" rel="noopener"><button class="small">${esc(t.name)}</button></a>`).join(" ")}</p>`).join("");

/* ================= 調査（対象を指定） ================= */
const RECON_QUESTIONS = [
  { type: "noul", id: "legit", instructions: "この対象は公的機関・大手・正規の運営者のものと考えられるか" },
  { type: "score", id: "risk", instructions: "なりすまし・詐欺・不正の疑いの強さ", levels: ["0", "1", "2", "3", "4", "5"] },
  { type: "choice", id: "issue", instructions: "最も注意すべき点", options: ["登録が新しい", "送信認証が未設定", "脅威情報あり", "見た目が似た文字", "使い捨て・匿名の手段", "特に問題なし"] },
  { type: "noul", id: "need_more", instructions: "結論を出す前に追加の確認が必要か" },
];
let reconResults = [];
const splitTargets = raw => { const toks = raw.split(/[,\n]/).map(x => x.trim()).filter(Boolean); const out = []; for (let i = 0; i < toks.length; i++) { if (/^-?\d+(\.\d+)?$/.test(toks[i]) && /^-?\d+(\.\d+)?$/.test(toks[i + 1] || "")) { out.push(`${toks[i]},${toks[i + 1]}`); i++; } else out.push(toks[i]); } return out.map(detectTarget); };
const rTypesPreview = () => { const ts = splitTargets($("#r-q").value); $("#r-types").innerHTML = ts.length ? ts.map(t => `<span class="chip ${t.type === "person" ? "alert" : "on"}">${esc(TARGET_TYPES[t.type] || t.type)}: ${esc(t.value.slice(0, 30))}</span>`).join(" ") : '<span class="small muted">判定される種類がここに出ます（接頭辞で指定も可: corp: / place: / user: / mail: / tel: / ip: / hash: / flight: / ship: / btc: / eth: / cve: / img:）</span>'; };
$("#r-q").oninput = rTypesPreview; $("#r-q").addEventListener("keydown", e => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); $("#r-run").click(); } });
$("#r-fw-open").onclick = e => { e.preventDefault(); const box = $("#r-fw"); box.classList.toggle("hidden"); if (!box.innerHTML) box.innerHTML = "<table><tr><th>カテゴリ</th><th>対象</th><th>自動（API）</th><th>端末内</th><th>リンク</th><th>方針</th></tr>" + FRAMEWORK.map(c => `<tr><td><b>${esc(c.cat)}</b></td><td class="small">${(c.types || []).map(t => TARGET_TYPES[t] || t).join("、")}</td><td class="small">${(c.tools || []).filter(t => t.kind === "auto").map(t => esc(t.name)).join("<br>")}</td><td class="small">${(c.tools || []).filter(t => t.kind === "local").map(t => esc(t.name)).join("<br>")}</td><td class="small">${(c.tools || []).filter(t => t.kind === "link").map(t => esc(t.name)).join("、")}</td><td class="small ${c.no ? "bad" : "muted"}">${esc(c.no || c.note || "")}</td></tr>`).join("") + "</table>"; };
function savedTargets() { try { const q = JSON.parse(localStorage.getItem("jev.targets") || "[]"); $("#r-saved").innerHTML = q.map(x => `<option value="${esc(x)}">`).join(""); return q; } catch { return []; } } savedTargets();
$("#r-run").onclick = async () => { const raw = $("#r-q").value.trim(); if (!raw) { $("#r-q").focus(); return status("対象を入れてください"); } const targets = splitTargets(raw); $("#r-run").disabled = true; showSteps(false); reconResults = []; $("#r-out").innerHTML = ""; try { localStorage.setItem("jev.targets", JSON.stringify([raw, ...savedTargets().filter(x => x !== raw)].slice(0, 20))); } catch { }
  for (const t of targets) { const box = document.createElement("div"); box.className = "summary"; box.innerHTML = `<b>${esc(TARGET_TYPES[t.type] || t.type)}: ${esc(t.value)}</b> <span class="muted small" id="r-st"></span>`; $("#r-out").appendChild(box); const st = box.querySelector("#r-st"); st.id = "";
    try { if (t.type === "keyword") { box.innerHTML += `<p class="small">キーワードは「情報収集」で扱います → <button class="small r-go" data-q="${esc(t.value)}">情報収集で収集する</button></p>`; box.querySelector(".r-go").onclick = ev => { $("#o-q").value = ev.target.dataset.q; showTab("osint"); $("#o-run").click(); }; continue; }
      const R = await investigate(t, m => st.textContent = m); reconResults.push(R); box.replaceWith(renderRecon(R)); } catch (e) { box.innerHTML += `<p class="bad">失敗: ${esc(e.message)}</p>`; } }
  $("#r-run").disabled = false; status(""); if (reconResults.length > 1) drawGraph(reconResults); if (isMobile) $("#r-out").scrollIntoView({ behavior: "smooth", block: "start" }); };
function renderRecon(R) { const d = document.createElement("div"); d.className = "card"; const kv = rows => "<table>" + Object.entries(rows).filter(([, v]) => v != null && v !== "").map(([k, v]) => `<tr><td style="width:30%">${esc(k)}</td><td class="small">${/^https?:\/\//.test(String(v)) ? `<a href="${esc(v)}" target="_blank" rel="noopener">${esc(v)}</a>` : esc(String(v))}</td></tr>`).join("") + "</table>"; const cats = {}; for (const l of R.links) (cats[l.cat] ??= []).push(l);
  d.innerHTML = `<h2>${esc(TARGET_TYPES[R.type] || R.type)}: ${esc(R.target.value)}</h2>${R.warnings.length ? `<div class="summary"><b>注意</b><ul class="small">${R.warnings.map(w => `<li>${esc(w)}</li>`).join("")}</ul></div>` : ""}${["domain", "url", "ip", "email"].includes(R.type) ? `<div class="r-jev"><p class="hint">${jev ? "JEV がこの対象の根拠を読んで判定中…" : "モデルを読み込むと、JEV が根拠を読んで「正規か／なりすましの疑い／注意点」を判定します"}</p></div>` : ""}${R.cards.map(c => `<details ${R.cards.length <= 4 ? "open" : ""}><summary>${esc(c.title)}${c.url ? ` <a href="${esc(c.url)}" target="_blank" rel="noopener" class="small">開く</a>` : ""}</summary>${kv(c.rows)}</details>`).join("")}${R.evidence.length ? `<details><summary>根拠として使える要約（${R.evidence.length} 行）</summary><ul class="small">${R.evidence.map(e => `<li>${esc(e)}</li>`).join("")}</ul><button class="small r-ctx">→ 情報収集の根拠に追加</button></details>` : ""}${Object.keys(cats).length ? `<details><summary>各サービスで開く（${R.links.length} リンク）</summary>${Object.entries(cats).map(([c, ls]) => `<p class="small"><b>${esc(c)}</b> ${ls.map(l => `<a href="${esc(l.url)}" target="_blank" rel="noopener"><button class="small">${esc(l.name)}</button></a>`).join(" ")}</p>`).join("")}</details>` : ""}${R.entities.length > 1 ? `<details><summary>関係図（${R.entities.length} 要素、Maltego 風）</summary><canvas class="r-graph" width="720" height="360"></canvas></details>` : ""}<p><button class="small r-json">この調査を JSON で保存</button> <button class="small r-note">実験ノートに保存</button></p>`;
  d.querySelector(".r-ctx")?.addEventListener("click", () => { $("#o-ctx").value = [...oCtx(), ...R.evidence].join("\n"); status("根拠に追加しました（情報収集タブ）"); }); d.querySelector(".r-json").onclick = () => download(`recon-${R.type}-${Date.now()}.json`, JSON.stringify({ version: VERSION, time: new Date().toISOString(), ...R }, null, 1)); d.querySelector(".r-note").onclick = async () => { await saveNote({ kind: "recon", name: `調査: ${R.target.value}`, model: jev?.name, target: R.target, evidence: R.evidence, warnings: R.warnings, judged: R.judged || null }); status("保存しました"); };
  const g = d.querySelector(".r-graph"); if (g) drawEntityGraph(g, [R]);
  const rj = d.querySelector(".r-jev"); if (jev && rj && R.evidence.length >= 2) reconJudge(R, rj); return d; }
async function reconJudge(R, el) { const state = [...R.warnings.map(w => "注意: " + w), ...R.evidence].join("\n"); try { const r = await jev.decide(state, RECON_QUESTIONS, null, curOpts()); R.judged = r.answers.map(a => ({ id: a.id, label: lab(a), confidence: a.confidence })); const A = Object.fromEntries(r.answers.map(a => [a.id, a])); const risk = A.risk.score; el.innerHTML = `<div class="summary"><b>JEV の判定</b>（${esc(jev.name)}、${r.latency_ms.toFixed(0)} ms、端末内）<div class="chips"><span class="flag ${A.legit.noul ? "on" : "alert"}">正規の運営者 ${A.legit.noul ? "✓" : "?"} <span class="muted">${pc(A.legit.confidence)}</span></span><span class="flag ${risk >= 3 ? "alert" : ""}">なりすまし・詐欺の疑い ${risk.toFixed(1)}/5</span><span class="flag on">注意点: ${esc(A.issue.choice)} <span class="muted">${pc(A.issue.confidence)}</span></span><span class="flag ${A.need_more.noul ? "alert" : ""}">追加確認 ${A.need_more.noul ? "必要" : "不要"}</span></div><p class="hint">${risk >= 3 ? "疑いが強い：リンク先（VirusTotal・OTX・Safe Browsing）で裏取りし、当該サイトへの入力は避ける。" : risk >= 1.5 ? "グレー：注意点を確認してから判断。" : "問題は見当たらない（ただし JEV は根拠行だけを読んでいる）。"}</p></div>`; } catch (e) { el.innerHTML = `<p class="muted small">JEV 判定失敗: ${esc(e.message)}</p>`; } }
function drawEntityGraph(c, results) { const g = c.getContext("2d"); const dark = document.documentElement.dataset.theme === "dark" || (matchMedia("(prefers-color-scheme:dark)").matches && document.documentElement.dataset.theme !== "light"); g.fillStyle = dark ? "#171b21" : "#fff"; g.fillRect(0, 0, c.width, c.height); const nodes = [], edges = []; const id = new Map(); const add = (t, v) => { const k = t + ":" + v; if (!id.has(k)) { id.set(k, nodes.length); nodes.push({ t, v }); } return id.get(k); }; for (const R of results) { const root = add(R.type, R.target.value); for (const e of R.entities.slice(0, 40)) { if (e.value === R.target.value) continue; edges.push([root, add(e.type, e.value), e.rel]); } }
  const col = { domain: "#0b6e99", host: "#0f766e", ip: "#b45309", email: "#7c3aed", username: "#be123c", place: "#15803d", org: "#6b7280", url: "#0b6e99", coords: "#15803d" }; const W = c.width, H = c.height; const pos = nodes.map((n, i) => { const roots = results.map(R => R.type + ":" + R.target.value); const ri = roots.indexOf(n.t + ":" + n.v); if (ri >= 0) return { x: W / 2 + (results.length > 1 ? (ri - (results.length - 1) / 2) * 220 : 0), y: H / 2 }; const a = i / nodes.length * Math.PI * 2; return { x: W / 2 + Math.cos(a) * (W / 2 - 70), y: H / 2 + Math.sin(a) * (H / 2 - 30) }; });
  g.font = "11px system-ui"; g.strokeStyle = dark ? "#2a3039" : "#d9dde3"; for (const [a, b] of edges) { g.beginPath(); g.moveTo(pos[a].x, pos[a].y); g.lineTo(pos[b].x, pos[b].y); g.stroke(); } nodes.forEach((n, i) => { g.fillStyle = col[n.t] || "#6b7280"; g.beginPath(); g.arc(pos[i].x, pos[i].y, 6, 0, 7); g.fill(); g.fillStyle = dark ? "#e6e8eb" : "#1a1d21"; g.fillText(String(n.v).slice(0, 28), pos[i].x + 8, pos[i].y + 4); }); }
function drawGraph(results) { const c = document.createElement("canvas"); c.width = 900; c.height = 420; const d = document.createElement("div"); d.className = "card"; d.innerHTML = "<h2>関係図（すべての対象）</h2>"; d.appendChild(c); $("#r-out").prepend(d); drawEntityGraph(c, results); }

/* ================= boot ================= */
setQuestions([]); refreshQSets(); $("#ver").textContent = VERSION;
await loadIndex(); storageInfo();
try { const lastM = localStorage.getItem("jev.lastModel"); if (lastM && models.some(m => m.name === lastM)) $("#model").value = lastM; else if (models.some(m => m.name === "jev_ja_30m")) $("#model").value = "jev_ja_30m"; $("#model").onchange(); } catch { }
try { const t = localStorage.getItem("jev.tab"); showTab(t && $("#t-" + t) ? t : "home"); } catch { showTab("home"); }
if ("serviceWorker" in navigator) navigator.serviceWorker.register("sw.js").then(() => setTimeout(offlineCheck, 800));
try { const m = models.find(x => x.name === $("#model").value); if (localStorage.getItem("jev.lastModel") && (m?.kind === "open-jev-onnx" || await isStored($("#model").value) || (await store.keys()).includes($("#model").value + "/model.onnx"))) $("#load").click(); } catch { }
